PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS state(id INTEGER PRIMARY KEY CHECK(id=1), epoch INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,dept TEXT NOT NULL,salt BLOB NOT NULL,verifier BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(digest TEXT PRIMARY KEY,uid TEXT NOT NULL REFERENCES users,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS docs(id TEXT PRIMARY KEY,title TEXT NOT NULL,dept TEXT NOT NULL,owner TEXT NOT NULL REFERENCES users,version INTEGER NOT NULL,acl_version INTEGER NOT NULL,public INTEGER NOT NULL,filename TEXT NOT NULL,original BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS grants(doc TEXT NOT NULL REFERENCES docs ON DELETE CASCADE,kind TEXT NOT NULL,target TEXT NOT NULL,PRIMARY KEY(doc,kind,target));
CREATE TABLE IF NOT EXISTS chunks(id TEXT PRIMARY KEY,doc TEXT NOT NULL REFERENCES docs ON DELETE CASCADE,version INTEGER NOT NULL,acl_version INTEGER NOT NULL,page INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,body TEXT NOT NULL,vector TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS chunks_doc ON chunks(doc);
CREATE TABLE IF NOT EXISTS answers(id TEXT PRIMARY KEY,uid TEXT NOT NULL REFERENCES users,epoch INTEGER NOT NULL,q TEXT NOT NULL,body TEXT NOT NULL,refs TEXT NOT NULL,config TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS answers_cache ON answers(uid,epoch,q,config);
CREATE TABLE IF NOT EXISTS audit(seq INTEGER PRIMARY KEY,id TEXT NOT NULL,uid TEXT NOT NULL,time TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),event TEXT NOT NULL,decision TEXT NOT NULL,reason TEXT NOT NULL,epoch INTEGER,refs TEXT NOT NULL,model TEXT NOT NULL,retriever TEXT NOT NULL,ms REAL NOT NULL);

